    33.17
  ],
  "indicator_readings": [
    {
      "indicator": "Fechamento",
      "reading": "R$30,20",
      "interpretation": "Fechamento abaixo das médias; confirma pressão vendedora no curto prazo."
    },
    {
      "indicator": "MM20",
      "reading": "R$31,4290",
      "interpretation": "MM20 acima do preço; tendência de curto prazo descendente (MM20 < MM50 < MM200)."
    },
    {
      "indicator": "MM50",
      "reading": "R$32,5912",
      "interpretation": "Média de médio prazo acima do preço; confirma estrutura baixista."
    },
    {
      "indicator": "MM200",
      "reading": "R$33,1716",
      "interpretation": "Média de longo prazo bem acima do preço; tendência de longo prazo ainda negativa."
    },
    {
      "indicator": "EMA9",
      "reading": "R$30,9220",
      "interpretation": "EMA9 abaixo da EMA21 e do preço; curto prazo dominado pelos vendedores."
    },
    {
      "indicator": "EMA21",
      "reading": "R$31,4474",
      "interpretation": "EMA21 acima do preço; resistência de curto/médio prazo próxima."
    },
    {
      "indicator": "MACD",
      "reading": "-0,5784",
      "interpretation": "MACD negativo e abaixo da linha de sinal — momentum vendedor persistente."
    },
    {
      "indicator": "MACD_signal",
      "reading": "-0,5423",
      "interpretation": "Linha de sinal negativa; confirma contexto de baixa enquanto MACD permanecer abaixo."
    },
    {
      "indicator": "MACD_hist",
      "reading": "-0,0361",
