    },
    {
      "indicator": "Bandas de Bollinger (lower/mid/upper)",
      "reading": "R$30,2217 / R$31,4290 / R$32,6363",
      "interpretation": "Preço tocou/ficou ligeiramente abaixo da banda inferior — movimento extremo e possível repique técnico, mas atenção à confirmação."
    },
    {
      "indicator": "RSI14",
      "reading": "28,6806",
      "interpretation": "RSI < 30: condição de sobrevenda; potencial para repique de curtíssimo prazo, porém não elimina a tendência de baixa."
    },
    {
      "indicator": "Volume",
      "reading": "27.202.774.200",
      "interpretation": "Volume do pregão de referência acima de pregões recentes (ex.: 30/04, 29/04, 26/04) — confirma pressão de venda no movimento descendente."
    }
  ]
